window.COURSE_CONTENT_YAML = "# Edit this file, then run: scripts/build-course\n#\n# Each block renders as the episode (+ reading) on the left and the practice\n# path on the right: exercise in class, vignette in recitation, homework at\n# home. Titles, thumbnails, icons, navigation anchors, and conventional\n# filenames are generated automatically.\n#\n# Optional per block:\n#   dates:                 # yyyy-mm-dd; the page marks the current step\n#     class: '2026-08-31'\n#     recitation: '2026-09-04'\n#     homework: '2026-09-06'\n#   exercise:              # only if the in-class exercise has downloads or a video\n#     links: [{label: Exercise, file: Classwork/Classwork_A1.pdf}]\n#     video: <youtube id>  # also allowed on vignette: and homework: — shows a small thumbnail on the step\n#   extras:                # optional material; sits on the path above the episode\n#     - name: Simulating a Market\n#       video: <youtube id>\n\nparts:\n  A:\n    title: The Core Economic Idea\n    tagline: better choices can benefit everyone\n    links: [{label: Skillsheet, file: Parts/A/A_Skillsheet.pdf}]\n    introduction: >-\n      Part A explores one of the most profound insights in all of social science: we have both preferences and scarcity which means every choice requires giving something up, and that measuring the cost of a choice by the value of what we give up, there turns out to be a fundamental reason to coordinate with others. These concepts explain why we specialize, why cities flourish, and how strangers working together can create prosperity that benefits everyone. These are the models that make it possible to see the invisible forces that make civilization possible.\n    homework_defaults:\n      due: Sunday, September 4\n    sections:\n      - block: A0\n        nav: Econ\n        steps:\n          - name: Syllabus Quiz\n            where: home\n            date: '2026-08-30'\n            due: Sunday, August 30\n            links: [{label: Syllabus, file: Syllabus/Syllabus.pdf}]\n        title: What is microeconomics?\n        description: >-\n          Microeconomics is about how we make decisions under constraints that arise from having both preferences and scarcity.\n        episode:\n          video: qMDU1QYKYss\n          links: [{label: Animations, file: animations/A0/, icon: fa fa-desktop}]\n          description: Economics is not *about* money.\n        reading:\n          chapter: 1\n          topic: Welcome to economics\n\n      - block: A1\n        nav: PPF\n        title: The production possibility frontier\n        description: The PPF shows us what's attainable as individuals and as a society.\n        episode:\n          video: po4kip5m_QY\n          links: [{label: Animations, file: animations/A1/, icon: fa fa-desktop}]\n          description: The landscape of what's possible\n        reading:\n          chapter: 2\n          topic: Choice in a world of scarcity\n        exercise:\n        vignette:\n          description: PPF practice problems\n        homework:\n          file: A1\n        dates:\n          class: '2026-08-26'\n          recitation: '2026-09-04'\n          homework: '2026-08-30'\n\n      - block: A2\n        nav: Specialization\n        title: Comparative advantage and specialization\n        description: >-\n          Minimizing opportunity cost by specializing in one's comparative advantage can bend out the PPF.\n        episode:\n          video: nclNGfY-3eA\n          links: [{label: Animations, file: animations/A2/, icon: fa fa-desktop}]\n          description: Specialization\n        reading:\n          chapter: 19\n          topic: International trade\n        exercise:\n        vignette:\n          description: Specialization practice problems\n        dates:\n          class: '2026-08-31'\n          recitation: '2026-09-04'\n          homework: '2026-09-06'\n\n      - block: A3\n        nav: Trade\n        title: Trade\n        description: Trade based on comparative advantage makes both parties better off simultaneously.\n        episode:\n          video: v_s4dO1AD5Y\n          description: Trade\n        reading:\n          name: Reading A3\n          description: No reading in this block\n        vignette:\n          description: Trade practice problems\n        dates:\n          class: '2026-09-02'\n          recitation: '2026-09-04'\n          homework: '2026-09-06'\n\n      - checkpoint:\n          date: '2026-09-09'\n          description: >-\n            Checkpoint A covers everything in Part A. You will begin to learn that if you understand the concepts and do the work in the Vignettes, Homework, and Demo, you're going to be in good shape on the Checkpoint.\n          demo:\n            video: KH0MkPxWsig\n\n  B:\n    title: How Competitive Markets Work\n    tagline: prices can coordinate buyers and sellers\n    introduction: >-\n      Part B reveals how markets solve the coordination problem from Part A. Through the elegant dance of supply and demand, prices emerge to coordinate economic activity and guide society toward efficiency. These aren't just abstract curves—they're the invisible forces that determine what gets produced, who gets what, and how resources flow through the economy. By the end of Part B, you'll understand why competitive markets are one of humanity's greatest innovations for creating prosperity.\n    sections:\n      - block: B1\n        nav: Demand\n        title: Demand\n        description: Demand curves show how much consumers are willing to buy at each price.\n        episode:\n          video: 9HUh9qWDSr4\n          description: \"*This video introduces the demand curve as a way of organizing buyers' preferences.*\"\n        reading:\n          chapter: 3\n          topic: Demand and supply\n        vignette:\n          description: \"*Demand practice problems*\"\n          files: B1\n        homework:\n          due: Wednesday September 25\n        dates:\n          class: '2026-09-14'\n          recitation: '2026-09-18'\n          homework: '2026-09-20'\n\n      - block: B2\n        nav: Supply\n        title: Supply\n        description: Supply curves show how much producers are willing to sell at each price.\n        episode:\n          video: 0WoBKpFMLwo\n          description: \"*This video introduces the supply curve and how it helps answer Part B's questions.*\"\n        reading:\n          name: Chapter (continued)\n          description: Continues Chapter 3 from Block B1\n        vignette:\n          description: \"*Supply practice problems*\"\n          files: B2\n        dates:\n          class: '2026-09-16'\n          recitation: '2026-09-18'\n          homework: '2026-09-20'\n\n      - block: B3\n        nav: Equilibrium\n        title: Equilibrium\n        description: Markets find the equilibrium price where quantity supplied equals quantity demanded.\n        episode:\n          video: 8CQ3D2Kv2i0\n          description: >-\n            *This video introduces shortage and surplus and the incentives of buyers and sellers to move prices toward equilibrium.*\n        reading:\n          chapter: 3\n          topic: Price ceilings and price floors\n        vignette:\n          description: \"*Markets practice problems*\"\n          files: B3\n        extras:\n          - name: Simulating a Market\n            video: PNtKXWNKGN8\n            description: \"*Simulating a Market - excellent video from one of my favorite Youtube channels!*\"\n        dates:\n          class: '2026-09-21'\n          recitation: '2026-09-25'\n          homework: '2026-09-27'\n\n      - block: B4\n        nav: Efficiency\n        title: Efficiency\n        description: Competitive markets maximize total surplus, achieving social efficiency.\n        episode:\n          video: RC9vcoqQm-U\n          description: >-\n            *This video introduces government price controls to show that the market maximizes total surplus in some environments.*\n        reading:\n          chapter: 3\n          topic: Demand, supply, and efficiency\n        vignette:\n          description: \"*Efficiency practice problems*\"\n        dates:\n          class: '2026-09-23'\n          recitation: '2026-09-25'\n          homework: '2026-09-27'\n\n      - block: B5\n        nav: Elasticity\n        title: Elasticity\n        description: Elasticity measures how responsive quantity is to changes in price, income, or other factors.\n        episode:\n          description: \"*Elasticity measures responsiveness*\"\n        reading:\n          name: Reading B5\n        vignette:\n          description: \"*Elasticity practice problems*\"\n        dates:\n          class: '2026-09-28'\n          recitation: '2026-10-02'\n          homework: '2026-10-04'\n\n      - block: B6\n        nav: Comparative Statics\n        title: Comparative Statics\n        description: Comparative statics analyzes how equilibrium changes when supply or demand conditions shift.\n        episode:\n          description: \"*How markets respond to changes*\"\n        reading:\n          name: Reading B6\n        vignette:\n          description: \"*Comparative statics practice problems*\"\n        dates:\n          class: '2026-09-28'\n          recitation: '2026-10-02'\n          homework: '2026-10-04'\n\n      - block: B7\n        nav: Tariffs\n        title: Tariffs\n        description: >-\n          International trade improves welfare but also creates winners and losers, which can lead to political pressure for protectionist policies like tariffs.\n        episode:\n          video: Kxq2E69dpCA\n          description: \"*International Trade*\"\n        reading:\n          chapter: 20\n          topic: Globalization and protectionism\n        vignette:\n          description: \"*International trade practice problems*\"\n          files: C1\n        dates:\n          class: '2026-09-28'\n          recitation: '2026-10-02'\n          homework: '2026-10-04'\n\n      - checkpoint:\n          date: '2026-09-30'\n          description: >-\n            Checkpoint B covers everything in Part B. If you understand the concepts and do the work in the Vignettes, Homework, and Demo, you're going to be in good shape on the Checkpoint.\n          demo:\n            video: yG7ahMJe8iA\n\n  C:\n    title: Externalities\n    tagline: externalized costs and benefits lead to inefficient markets\n    introduction: >-\n      Part B showed us how markets coordinate perfectly when conditions are right, delivering efficient outcomes that maximize total surplus. But what happens when those perfect conditions break down? Part C reveals the dark side of markets—when private incentives misalign with social welfare, creating externalities and market failures that require government intervention to restore efficiency. You'll discover how pollution, taxes, and corrective policies can either harm or heal market outcomes.\n    sections:\n      - block: C1\n        nav: Externalities\n        title: Externalities\n        description: When private costs don't equal social costs, markets produce too much or too little, creating inefficiency.\n        episode:\n          video: uxPoYbtzYbM\n          description: \"*Externalities*\"\n        reading:\n          chapter: 12\n          topic: Environmental protection and negative externalities\n          video: prohFxS0E1I\n        vignette:\n          video: xKK5JBPXGsg\n          description: \"*Externalities practice problems*\"\n          files: C1\n        homework:\n          due: Due Date TBD\n          practice: hwc\n        dates:\n          class: '2026-10-05'\n          recitation: '2026-10-09'\n          homework: '2026-10-11'\n\n      - block: C2\n        nav: Taxes\n        title: Taxes\n        description: Taxes create deadweight loss by driving a wedge between what buyers pay and sellers receive, reducing total surplus.\n        episode:\n          video: R2NctbU80y0\n          description: \"*Taxes and Welfare*\"\n        reading:\n          chapter: 5\n          topic: Elasticity and tax incidence\n          video: AYJh3NefuUM\n        vignette:\n          description: \"*Taxes practice problems*\"\n          files: C2\n          solutions: false\n        homework:\n          due: Friday October 18\n        dates:\n          class: '2026-10-07'\n          recitation: '2026-10-09'\n          homework: '2026-10-11'\n\n      - block: C3\n        nav: Corrective Taxes\n        title: Corrective Taxes\n        description: Pigouvian taxes can internalize externalities and restore market efficiency by aligning private and social costs.\n        episode:\n          video: W0eAtssLxmk\n          description: \"*Corrective Taxes*\"\n        reading:\n          chapter: 12\n          topic: Environmental protection and negative externalities\n          video: prohFxS0E1I\n        vignette:\n          description: \"*Corrective taxes practice problems*\"\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-10-12'\n          recitation: '2026-10-16'\n          homework: '2026-10-18'\n\n      - checkpoint:\n          date: '2026-10-14'\n          description: >-\n            Checkpoint C covers everything in Part C. You will begin to learn that if you understand the concepts and do the work in the Vignettes, Homework, and Demo, you're going to be in good shape on the Checkpoint.\n          demo:\n            video: lna7UhNOOro\n\n  D:\n    title: Strategic Interaction\n    tagline: strategic interaction often leads to inefficient markets\n    introduction: >-\n      Part D pushes beyond market failures to explore situations where markets aren't even the right framework. Here we encounter public goods and common resources—goods that are entirely externalities with no private component. These situations demand a completely different approach: strategic thinking and game theory. You'll discover why cooperation is sometimes impossible even when everyone would benefit, and how understanding these dynamics reveals the hidden logic behind everything from environmental policy to international relations.\n    sections:\n      - block: D1\n        nav: Common Resources\n        title: Common Resources\n        description: >-\n          Common resources create market failures through the tragedy of the commons—when shared resources are overused because private incentives don't align with social benefits.\n        episode:\n          video: wd8LSB8nF7o\n          description: \"*Introducing non-excludable goods*\"\n        reading:\n          chapter: 13\n          topic: Positive externalities and public goods\n        vignette:\n          description: \"*Non-excludable goods practice problems*\"\n          files: D1\n        homework:\n          due: Friday November 1st\n        dates:\n          class: '2026-10-19'\n          recitation: '2026-10-23'\n          homework: '2026-10-25'\n\n      - block: D2\n        nav: Public Goods\n        title: Public Goods\n        description: >-\n          Public goods create free-rider problems because they are non-excludable and non-rivalrous, leading to under-provision by private markets and the need for government intervention.\n        episode:\n          video: Is0CQbUM-j8\n          description: \"*Baby game theory*\"\n        reading:\n          chapter: 13\n          topic: Positive externalities and public goods\n        vignette:\n          description: \"*Game theory practice problems*\"\n          files: D2\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-10-21'\n          recitation: '2026-10-23'\n          homework: '2026-10-25'\n\n      - block: D3\n        nav: Game Theory\n        title: Game Theory\n        description: >-\n          Strategic interaction and Nash equilibrium provide a framework for analyzing decisions when outcomes depend on what others do, revealing why cooperation often fails even when it would benefit everyone.\n        episode:\n          video: s_ed6uwHOQI\n          description: \"*Baby game theory*\"\n        reading:\n          name: Reading D3\n        vignette:\n          description: \"*Game theory practice problems*\"\n          files: D3\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-10-26'\n          recitation: '2026-10-30'\n          homework: '2026-11-01'\n\n        extras:\n          - name: Veritasium Game Theory\n            video: mScpHTIi-kM\n      - block: D4\n        nav: Voting\n        title: Voting\n        description: >-\n          Voting systems and collective choice reveal how individual preferences aggregate into social decisions, often leading to paradoxes and inefficiencies in democratic decision-making.\n        episode:\n          description: \"*Voting and collective choice*\"\n        reading:\n          name: Reading D4\n        vignette:\n          description: \"*Voting systems practice problems*\"\n          files: D4\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-10-26'\n          recitation: '2026-10-30'\n          homework: '2026-11-01'\n\n      - checkpoint:\n          date: '2026-10-28'\n          description: >-\n            Checkpoint D covers everything in Part D. You will begin to learn that if you understand the concepts and do the work in the Vignettes, Homework, and Demo, you're going to be in good shape on the Checkpoint.\n          demo:\n            video: BYrsSbLdJuQ\n            file: D1\n\n  E:\n    title: Sellers\n    tagline: market power leads to inefficient markets\n    introduction: >-\n      We've mastered coordination and market efficiency—now it's time to explore what happens when sellers have market power. Part E reveals how firms convert inputs to outputs, minimize costs, and maximize profits. You'll discover the dramatic difference between perfect competition and monopoly, and why market structure fundamentally determines economic outcomes. These insights unlock the mystery of why some markets thrive while others exploit consumers—and what we can do about it.\n    sections:\n      - block: E1\n        nav: Costs\n        title: Costs of Production\n        description: Firms transform inputs into outputs through production functions and minimize costs to determine their supply decisions.\n        episode:\n          video: J0Y6XzwSfls\n          description: \"*The costs of production*\"\n        reading:\n          chapter: 7\n          topic: Production, costs, and industry structure\n        vignette:\n          description: \"*Production costs practice problems*\"\n          files: E1\n        homework:\n          due: Sunday November 10th\n        dates:\n          class: '2026-11-02'\n          recitation: '2026-11-06'\n          homework: '2026-11-08'\n\n      - block: E2\n        nav: Competition\n        title: Competitive Firms\n        description: Perfect competition emerges when firms are price-takers with no individual market power over the equilibrium price.\n        episode:\n          video: YN4ZkPBS_O8\n          description: \"*Competitive firms*\"\n        reading:\n          chapter: 8\n          topic: Perfect competition\n        vignette:\n          description: \"*Competitive firms practice problems*\"\n          files: E2\n        homework:\n          due: Monday November 18th\n        dates:\n          class: '2026-11-04'\n          recitation: '2026-11-06'\n          homework: '2026-11-08'\n\n      - block: E3\n        nav: Monopoly\n        title: Monopoly\n        description: Market power allows firms to influence prices and capture profits at the expense of consumer welfare and economic efficiency.\n        episode:\n          video: N0mbUXYMwdw\n          description: \"*Monopoly firms*\"\n        reading:\n          chapter: 9\n          topic: Monopoly\n        vignette:\n          description: \"*Monopoly practice problems*\"\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-11-09'\n          recitation: '2026-11-13'\n          homework: '2026-11-15'\n\n      - block: E4\n        nav: Market Structures\n        title: Market Structures\n        description: Comparing perfect competition, monopolistic competition, oligopoly, and monopoly reveals how market structure determines economic outcomes.\n        episode:\n          video: UIXf362W-rU\n          description: \"*Comparing market structures*\"\n          links:\n            - label: Notes\n              file: Parts/E/E4_Duopoly/04_Handwritten.pdf\n        reading:\n          chapter: 10\n          topic: Monopolistic competition and oligopoly\n        vignette:\n          description: \"*Market structures practice problems*\"\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-11-11'\n          recitation: '2026-11-13'\n          homework: '2026-11-15'\n\n      - checkpoint:\n          date: '2026-11-30'\n          description: >-\n            Checkpoint E covers everything in Part E. You will begin to learn that if you understand the concepts and do the work in the Vignettes, Homework, and Demo, you're going to be in good shape on the Checkpoint.\n          demo:\n            video: UZDvSTNbv0w\n          extras:\n            - name: Demo E3\n              video: jwxiRNAPBLc\n              files: E3\n\n\n  F:\n    title: Buyers\n    tagline: people respond to many interacting incentives\n    introduction: >-\n      Part F completes our economic journey by revealing the elegant mathematics of human choice. After exploring how markets work and fail, we now discover how budget constraints and preferences create the demand curves that drive everything. You'll learn why consumers make the choices they do, how income from factor markets shapes purchasing power, and how utility maximization creates the predictable patterns we see in real markets. These insights don't just explain buyer behavior—they reveal the hidden logic behind every purchase decision you'll ever make.\n    sections:\n      - block: F1\n        nav: Factor Markets\n        title: Factor Markets\n        description: Factor markets determine the income that households earn from selling their labor and capital, which becomes the budget constraint for consumer choice.\n        episode:\n          description: \"*Factor markets*\"\n        reading:\n          chapter: 4\n          topic: Labor and financial markets\n        vignette:\n          video: n3LpswjCp6w\n          description: \"*Factor markets practice problems with video walkthrough*\"\n          files: F1\n        homework:\n          due: Sunday December 8th\n        dates:\n          class: '2026-11-30'\n          recitation: '2026-12-04'\n          homework: '2026-12-06'\n\n      - block: F2\n        nav: Consumer Choice\n        title: Consumer Choice\n        description: Given their budget constraint from factor markets, consumers maximize utility by choosing the optimal combination of goods where marginal utility per dollar is equal across all goods.\n        episode:\n          description: \"*Consumer choice*\"\n        reading:\n          chapter: 6\n          topic: Consumer choices\n        vignette:\n          video: l2uq30_Cg10\n          description: \"*Consumer choice practice problems with video walkthrough*\"\n          files: F2\n          solution_file: Vignettes/Vignette_F2_sols_new.pdf\n        homework:\n          due: Due Date TBD\n        dates:\n          class: '2026-12-02'\n          recitation: '2026-12-04'\n          homework: '2026-12-06'\n\n      - checkpoint:\n          when: Final Exam Period\n          description: >-\n            You will begin to learn that if you understand the concepts and do the work in the Vignettes, Homework, and Demo, you're going to be in good shape on the Checkpoint.\n          demo:\n            video: zkn0CXaNOJY\n            file: F1\n          extras:\n            - name: Demo F2\n              video: DVHvgb_kJDY\n              files: F2\n";
window.COURSE_BLOCK_FILES = {"A1":{"exercise":"Parts/A/A1_The_PPF/Exercise/Exercise_A1.pdf","homework":"Parts/A/A1_The_PPF/Homework/Homework_A1.pdf"},"A2":{"exercise":"Parts/A/A2_Advantage/Exercise/Exercise_A2.pdf"},"E1":{"homework_sols":"Parts/E/E1_Costs/Homework/Homework_E1_sols.pdf"},"E2":{"homework_sols":"Parts/E/E2_Competition/Homework/Homework_E2_sols.pdf"}};
